    public string? SystemRole =>
        _httpContextAccessor.HttpContext?.User.FindFirst("system_role")?.Value;

    public ClaimsPrincipal Principal =>
        _httpContextAccessor.HttpContext?.User ?? new ClaimsPrincipal();
